/bin/bash -lc "cat > src/util/checkoutRequest.mjs <<'EOF'
/**
 * Build the checkout request the storefront POSTs for a cart,
 * using the field names defined by the backend order request classes
 * (PersistableOrder / PersistablePayment).
 */
export function buildCheckoutRequest({
  cartCode,
  shippingOptionId,
  currency,
  paymentToken,
  paymentModule,
  amount,
  agreedToTerms,
  comments,
}) {
  const body = {
    // shipping option chosen from the shipping quote options
    quoteId: shippingOptionId,
    currency,
    // whether the terms and conditions were accepted
    termsAccepted: Boolean(agreedToTerms),
    // order comment
    orderNote: comments,
    payment: {
      paymentType: \"CREDITCARD\",
      transactionType: \"CAPTURE\",
      // the payment module, e.g. \"stripe\"
      processor: paymentModule,
      // the payment token created by the payment module
      cardToken: paymentToken,
      amount,
    },
  };

  return {
    method: \"POST\",
    path: "'`cart/${cartCode}/checkout`,
    body,
  };
}
EOF
node --input-type=module -e "import {buildCheckoutRequest} from '"'./src/util/checkoutRequest.mjs'; console.log(JSON.stringify(buildCheckoutRequest({cartCode:'ABC123', shippingOptionId: 7, currency:'USD', paymentToken:'tok_123', paymentModule:'stripe', amount: 42.5, agreedToTerms: true, comments:'gift wrap'}), null, 2));\""
